from flask import Flask, request, jsonify, make_response
import bcrypt
import jwt
import os
from datetime import datetime, timedelta
from functools import wraps

app = Flask(__name__)
users = []
next_id = 1
ACCESS_SECRET = os.getenv('JWT_ACCESS_SECRET', 'access-secret-key')
REFRESH_SECRET = os.getenv('JWT_REFRESH_SECRET', 'refresh-secret-key')

@app.route('/api/auth/register', methods=['POST'])
def register():
    global next_id
    data = request.json
    if any(u['email'] == data['email'] for u in users):
        return jsonify({'error': 'Bu email zaten kayitli'}), 409
    password_hash = bcrypt.hashpw(data['password'].encode(), bcrypt.gensalt(12))
    user = {'id': next_id, 'name': data['name'], 'email': data['email'],
            'password_hash': password_hash, 'role': 'user',
            'created_at': datetime.utcnow().isoformat()}
    next_id += 1
    users.append(user)
    return jsonify({'id': user['id'], 'name': user['name'],
                    'email': user['email'], 'createdAt': user['created_at']}), 201

@app.route('/api/auth/login', methods=['POST'])
def login():
    data = request.json
    user = next((u for u in users if u['email'] == data['email']), None)
    if not user or not bcrypt.checkpw(data['password'].encode(), user['password_hash']):
        return jsonify({'error': 'Gecersiz email veya sifre'}), 401
    access_token = jwt.encode({'userId': user['id'], 'role': user['role'],
        'exp': datetime.utcnow() + timedelta(minutes=15)}, ACCESS_SECRET)
    refresh_token = jwt.encode({'userId': user['id'],
        'exp': datetime.utcnow() + timedelta(days=7)}, REFRESH_SECRET)
    resp = make_response(jsonify({'accessToken': access_token}))
    resp.set_cookie('refreshToken', refresh_token, httponly=True,
                    secure=True, samesite='Strict', max_age=7*24*60*60)
    return resp

def authenticate(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.headers.get('Authorization', '')
        if not auth.startswith('Bearer '):
            return jsonify({'error': 'Token gerekli'}), 401
        try:
            decoded = jwt.decode(auth.split(' ')[1], ACCESS_SECRET, algorithms=['HS256'])
            request.user = decoded
        except jwt.ExpiredSignatureError:
            return jsonify({'error': 'Token suresi dolmus'}), 401
        except jwt.InvalidTokenError:
            return jsonify({'error': 'Gecersiz token'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/profile')
@authenticate
def profile():
    user = next((u for u in users if u['id'] == request.user['userId']), None)
    if not user:
        return jsonify({'error': 'Kullanici bulunamadi'}), 404
    return jsonify({'id': user['id'], 'name': user['name'],
                    'email': user['email'], 'role': user['role']})
